    customer_ids = get_value(("customer_ids", "customers", "nodes"), None)

    def is_dict(x):
        try:
            x.keys
            return True
        except Exception:
            return False

    def is_listlike(x):
        try:
            x.__len__
            x.__getitem__
            return True
        except Exception:
            return False

    if customer_ids is None:
        if is_dict(demands_raw):
            customer_ids = []
            try:
                for k in demands_raw:
                    if k != depot:
                        customer_ids.append(k)
            except Exception:
                customer_ids = []
        elif is_dict(coords):
            customer_ids = []
            try:
                for k in coords:
                    if k != depot:
                        customer_ids.append(k)
            except Exception:
                customer_ids = []
        elif is_listlike(dist_matrix):
            customer_ids = [i for i in range(len(dist_matrix)) if i != depot]
        else:
            customer_ids = []

    seen = {}
    filtered = []
    try:
        for c in customer_ids:
            if c != depot and c not in seen:
                seen[c] = 1
                filtered.append(c)
    except Exception:
        filtered = []
    customer_ids = filtered

    demands = {}
    if is_dict(demands_raw):
        try:
            for k in demands_raw:
                demands[k] = demands_raw[k]
        except Exception:
            demands = {}
    elif is_listlike(demands_raw):
        try:
            for i in range(len(demands_raw)):
                demands[i] = demands_raw[i]
        except Exception:
            demands = {}

    def demand_of(c):
        try:
            d = demands.get(c, 1)
        except Exception:
            d = 1
        try:
            if d is None:
                return 1
            return d
        except Exception:
            return 1

    xy = {}
    if is_dict(coords):
        try:
            for k in coords:
                xy[k] = coords[k]
        except Exception:
            xy = {}
    elif is_listlike(coords):
        try:
            for i in range(len(coords)):
                xy[i] = coords[i]
        except Exception:
            xy = {}

    def dist(a, b):
        if dist_matrix is not None:
            try:
                return dist_matrix[a][b]
            except Exception:
                pass
        try:
            pa = xy[a]
            pb = xy[b]
            dx = pa[0] - pb[0]
            dy = pa[1] - pb[1]
            return (dx * dx + dy * dy) ** 0.5
        except Exception:
            pass
        try:
            return abs(a - b)
        except Exception:
            return 0

    # Deterministic ordering: angle around depot if coordinates exist, else demand/ID.
    if depot in xy:
        try:
            dx0, dy0 = xy[depot][0], xy[depot][1]
            customer_ids.sort(key=lambda c: (((xy.get(c, (0, 0))[1] - dy0), (xy.get(c, (0, 0))[0] - dx0), c)))
        except Exception:
            customer_ids.sort(key=lambda c: (-demand_of(c), c))
    else:
        customer_ids.sort(key=lambda c: (-demand_of(c), c))

    # Build routes with nearest-feasible greedy growth.
    unassigned = customer_ids[:]
    routes = []

    while unassigned:
        route = []
        load = 0
        current = depot

        # Seed: choose the nearest feasible customer to depot; if none fits, take the first unassigned.
        seed = None
        seed_score = None
        for c in unassigned:
            d = demand_of(c)
            if capacity > 0 and d > capacity:
                continue
            if capacity <= 0 or load + d <= capacity:
                sc = (dist(depot, c), d, c)
                if seed is None or sc < seed_score:
                    seed = c
                    seed_score = sc
        if seed is None:
            seed = unassigned[0]

        route.append(seed)
        load += demand_of(seed)
        unassigned.remove(seed)
        current = seed

        while True:
            best = None
            best_score = None
            for c in unassigned:
                d = demand_of(c)
                if capacity > 0 and load + d > capacity:
                    continue
                sc = (dist(current, c), dist(depot, c), d, c)
                if best is None or sc < best_score:
                    best = c
                    best_score = sc
            if best is None:
                break
            route.append(best)
            load += demand_of(best)
            unassigned.remove(best)
            current = best

        routes.append(route)

    # Repair: if any route is empty (shouldn't happen), remove it.
    routes = [r for r in routes if r]

    # Local search: intra-route 2-opt.
    def route_cost(rt):
        if not rt:
            return 0
        total = dist(depot, rt[0])
        for i in range(len(rt) - 1):
            total += dist(rt[i], rt[i + 1])
        total += dist(rt[-1], depot)
        return total

    for idx in range(len(routes)):
        rt = routes[idx]
        n = len(rt)
        if n < 4:
            continue
        improved = True
        while improved:
            improved = False
            best_i = -1
            best_j = -1
            best_delta = 0
            for i in range(n - 2):
                a = depot if i == 0 else rt[i - 1]
                b = rt[i]
                for j in range(i + 2, n):
                    c = rt[j]
                    d = depot if j == n - 1 else rt[j + 1]
                    delta = (dist(a, c) + dist(b, d)) - (dist(a, b) + dist(c, d))
                    if delta < best_delta:
                        best_delta = delta
                        best_i = i
                        best_j = j
            if best_i >= 0:
                rt[best_i:best_j + 1] = rt[best_i:best_j + 1][::-1]
                improved = True
        routes[idx] = rt

    # Final sanity: ensure each customer exactly once; repair by deduplication if needed.
    seen = {}
    final_routes = []
    for rt in routes:
        new_rt = []
        for c in rt:
            if c != depot and c not in seen:
                seen[c] = 1
                new_rt.append(c)
        if new_rt:
            final_routes.append(new_rt)

    missing = []
    for c in customer_ids:
        if c not in seen:
            missing.append(c)

    if missing:
        # Insert missing customers into feasible routes with minimal extra cost.
        for c in missing:
            d = demand_of(c)
            best_route = None
            best_pos = None
            best_cost = None

            for r_idx in range(len(final_routes)):
                rt = final_routes[r_idx]
                load = 0
                for x in rt:
                    load += demand_of(x)
                if capacity > 0 and load + d > capacity:
                    continue
                for pos in range(len(rt) + 1):
                    prev = depot if pos == 0 else rt[pos - 1]
                    nxt = depot if pos == len(rt) else rt[pos]
                    inc = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                    sc = (inc, len(rt), r_idx, pos)
                    if best_route is None or sc < best_cost:
                        best_route = r_idx
                        best_pos = pos
                        best_cost = sc

            if best_route is None:
                final_routes.append([c])
            else:
                final_routes[best_route].insert(best_pos, c)

    return final_routes
